cd /tmp/sv-442dc3f6da6447899d9599041b683ff7/moderate-version-conflicts && dotnet list package --format json > after-cpm-packages.json 2>&1 && python3 -c "
import json
with open('baseline-packages.json') as f: b = json.load(f)
with open('after-cpm-packages.json') as f: a = json.load(f)
changes = []
unchanged = []
for bp, ap in zip(b['projects'], a['projects']):
    proj = bp['path'].split('/')[-1]
    bpkgs = {p['id']: p['resolvedVersion'] for fw in bp.get('frameworks',[]) for p in fw.get('topLevelPackages',[])}
    apkgs = {p['id']: p['resolvedVersion'] for fw in ap.get('frameworks',[]) for p in fw.get('topLevelPackages',[])}
    for pkg in sorted(set(list(bpkgs.keys()) + list(apkgs.keys()))):
        bv = bpkgs.get(pkg,'-')
        av = apkgs.get(pkg,'-')
        if bv != av:
            changes.append((proj,pkg,bv,av))
        else:
            unchanged.append((proj,pkg,bv))
print('=== CHANGES ===')
for c in changes: print(f'{c[0]:20s} {c[1]:40s} {c[2]:10s} -> {c[3]}')
if not changes: print('None')
print(f'\n=== UNCHANGED: {len(unchanged)} package-project pairs ===')
"

